"""Grammar coach: 41 short lessons from A1 to C, written for Bangla speakers by FamilyEnglish.

Each lesson is taught as a chat: a hello, the pattern (coloured parts), the rule in English and
Bangla, examples, then practice. Practice items:
  ("fill", prompt, [accepted answers])   type the missing word(s)
  ("fix",  wrong sentence, [accepted])   correct the sentence
  ("say",  sentence)                     say it aloud (scored by speech recognition)
  ("make", task, regex)                  make your own sentence that matches the pattern
"""

LEVELS = [
    ("A1", "Beginner", "শুরু"),
    ("A2", "Elementary", "প্রাথমিক"),
    ("B1", "Intermediate", "মধ্যম"),
    ("B2", "Upper intermediate", "উচ্চ-মধ্যম"),
    ("C", "Advanced", "উচ্চতর"),
]


def L(slug, level, icon, title, title_bn, sub, hello, formula, rule, examples, practice):
    return {"slug": slug, "level": level, "icon": icon, "title": title, "title_bn": title_bn, "sub": sub,
            "hello": hello, "formula": formula, "rule": rule, "examples": examples, "practice": practice}


